// RentStatusSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/digitenant/reports/rent/status/list/RentStatusSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import RentStatusActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const RentStatusSchema = {
  entity: 'rental_rent_status',
  label: 'Rent Status by Tenant',
  description: '',
  apiBase: apiRoutes.rentstatus?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: RentStatusActions,

  groupBy: 'tenant',
  groupLabel: 'Tenant',
  sortBy: 'owed desc',

  fields: [
    { key: 'invoices', label: 'Invoices', from: 'rent_invoices' },
    { key: 'billed', label: 'Billed', from: 'rent_invoices.total_amount', type: 'money' },
    { key: 'paid', label: 'Paid', from: 'rent_invoices.paid_amount', type: 'money' },
    { key: 'owed', label: 'Balance', calc: 'billed - paid', type: 'money' },
    { key: 'paid_pct', label: 'Paid %', calc: 'round(paid / billed * 100)' },
  ],

  remarks: [
    { if: 'paid == 0', tone: 'bad', title: 'NOT PAID', say: '{label} has paid nothing of the {billed} billed.' },
    { if: 'owed > 0', tone: 'watch', title: 'PART PAID', say: '{label} has paid {paid} of {billed} ({paid_pct}%), {owed} is still owed.' },
    { if: 'true', tone: 'good', title: 'PAID', say: '{label} has paid the full {billed}.' },
  ],

  headline: '{label} has the largest balance: {owed} of {billed} billed ({paid_pct}% paid).',
};
